// 前一个兄弟元素
let prevElementSibling = element.previousElementSibling;

// 下一个兄弟节点
let nextSibling = element.nextSibling;

// 下一个兄弟元素
let nextElementSibling = element.nextElementSibling;
```

## 七、事件处理

事件是 JavaScript 与用户交互的核心机制。

### 1. `addEventListener` 方法（推荐）

```javascript
let button = document.querySelector('#myButton');

button.addEventListener('click', function() {
    alert('按钮被点击了！');
});

// 可以添加多个事件监听器
button.addEventListener('mouseenter', function() {
    console.log('鼠标进入了按钮区域');
});
```

### 2. 常见事件类型

**鼠标事件**：`click`、`dblclick`、`mousedown`、`mouseup`、`mouseenter`、`mouseleave`、`mousemove`

**键盘事件**：`keydown`、`keyup`、`keypress`（已不推荐使用）

**表单事件**：`submit`、`change`、`input`、`focus`、`blur`

**窗口事件**：`load`、`resize`、`scroll`、`beforeunload`

### 3. 事件对象

事件处理函数会自动接收一个 `event` 参数，包含事件的详细信息。

```javascript
document.querySelector('#myInput').addEventListener('keydown', function(event) {
    console.log('按下的键：' + event.key);
    console.log('键码：' + event.keyCode);

    // 阻止默认行为（比如阻止表单提交）
    event.preventDefault();
});
```

### 4. 事件冒泡与事件委托

事件冒泡是指当一个元素上的事件被触发时，这个事件会逐层向上传播到它的父元素。利用这个机制，可以实现**事件委托**。

```javascript
// 为整个列表添加一个点击事件监听器
let list = document.querySelector('#myList');

list.addEventListener('click', function(event) {
    // event.target 是被点击的具体元素
    if (event.target.tagName === 'LI') {
        console.log('点击了列表项：' + event.target.textContent);
    }
});

// 这样就不需要为每个 <li> 单独绑定事件，即使动态添加的 <li> 也能响应点击
```

## 八、表单操作

### 1. 获取表单元素的值

```javascript
let input = document.querySelector('#username');
let value = input.value;  // 获取输入框的值

let checkbox = document.querySelector('#agree');
let isChecked = checkbox.checked;  // 获取复选框的选中状态
```

### 2. 表单验证与提交

```javascript
let form = document.querySelector('#loginForm');

form.addEventListener('submit', function(event) {
    // 阻止表单默认提交行为
    event.preventDefault();

    let username = this.querySelector('#username').value;
    let password = this.querySelector('#password').value;

    if (username === '' || password === '') {
        alert('请填写完整信息');
        return;
    }

    // 此处可进行 AJAX 提交或其他逻辑
    console.log('提交数据：', { username, password });
});
```

## 九、元素位置与尺寸

```javascript
let element = document.querySelector('#box');

// 获取元素相对于视口的位置
let rect = element.getBoundingClientRect();
console.log(rect.top, rect.left, rect.width, rect.height);

// 获取元素的滚动位置
let scrollTop = element.scrollTop;
let scrollLeft = element.scrollLeft;

// 获取元素内部尺寸（不含边框）
let clientWidth = element.clientWidth;
let clientHeight = element.clientHeight;

// 获取元素完整尺寸（含边框和内边距）
let offsetWidth = element.offsetWidth;
let offsetHeight = element.offsetHeight;
```

## 总结

DOM 操作是 JavaScript 与网页交互的核心能力。掌握如何获取元素、修改内容与样式、动态调整结构、处理用户事件，是构建交互式网页应用的基础。通过 DOM API，你可以让网页从静态的 HTML 文档，转变为动态的、可交互的 Web 应用。熟练运用选择器、事件机制和 DOM 遍历方法，将使你能够高效地实现各种前端交互功能。

